    console.error('save failed', e)
    throw e
  }
}

export const getUser = async (id, repo) => {
  try {
    return await repo.find(id)
  } catch (e) {
    return null
  }
}

export const listOrders = async (repo) => {
  try {
    return await repo.all()
  } catch (e) {
    return []
  }
}

export const isEligible = async (user, check) => {
  try {
    return await check(user)
  } catch (e) {
    return false
  }
}

export const validate = (item, rule) => {
  try {
    rule(item)
    return { item, ok: true }
  } catch (e) {
    return { item, error: String(e) }
  }
}

export const validateAll = (items, rule) => items.map((item) => validate(item, rule))

import express from 'express'

const app = express()

app.post('/users/:id/deactivate', async (req, res) => {
  try {
    await deactivateUser(req.params.id)
    res.status(204).end()
  } catch (e) {
    res.status(500).json({ error: 'failed to deactivate' })
  }
})

export const main = async () => {
  try {
    await run()
  } catch (e) {
    console.error(e)
    process.exitCode = 1
  }
}

export const chargeCard = async (order, gateway) => {
  try {
    return await gateway.charge(order)
  } catch (e) {
    throw new PaymentDeclinedError(order.id, { cause: e })
  }
}

export const withConn = async (fn, conn) => {
  try {
    return await fn(conn)
  } finally {
    await conn.close()
  }
}

export const loadConfig = (read) => {
  try {
    return JSON.parse(read())
  } catch (e) {
    return defaultConfig
  }
}

